  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}
.hc__card:focus-visible {
  outline: 2px solid var(--hc-accent);
  outline-offset: 2px;
}
.hc__foil, .hc__glare {
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  transform: translateZ(0);
