/* o que o projeto pode trocar com uma classe (largura, posi\xe7\xe3o, margem): na camada base, que vem antes das classes de
   componente e dos utilit\xe1rios (Tailwind v4) e perde para o CSS fora de camada (Tailwind v3, CSS Modules, CSS comum) */
@layer base {
  .cg-root { position: relative; width: 100%; margin: 0; }
}
.cg-root {
  aspect-ratio: 1;
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}
.cg-stage { position: absolute; inset: 0; }
/* o arraste na horizontal gira o globo; no toque, o gesto vertical continua rolando a p\xe1gina */
.cg-canvas {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  cursor: grab;
  opacity: 0;
  transition: opacity 1.2s ease;
  touch-action: pan-y;
}

/* os r\xf3tulos: nada de texto herdado da p\xe1gina, para ficarem iguais em qualquer projeto */
.cg-label {
  display: none;
  position: absolute;
  box-sizing: border-box;
  margin: 0 0 8px;
  padding: 2px 6px;
  font-family: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 9.6px;
  font-weight: 400;
  font-style: normal;
  font-variant: normal;
  font-feature-settings: normal;
  line-height: 1.5;
  letter-spacing: .08em;
  word-spacing: normal;
  text-align: left;
  text-indent: 0;
  text-transform: uppercase;
  text-shadow: none;
  white-space: nowrap;
  pointer-events: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: opacity .8s, filter .8s;
}
.cg-label--marker { background: #1a1a2e; color: #fff; }
.cg-label--arc { background: #fff; color: #1a1a2e; box-shadow: 0 1px 4px rgba(0, 0, 0, .1); }
.cg-label__tip {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translate3d(-50%, -1px, 0);
  border: 5px solid transparent;
}
.cg-label--marker .cg-label__tip { border-top-color: #1a1a2e; }
.cg-label--arc .cg-label__tip { border-top-color: #fff; }
/* presos aos pontos por CSS Anchor Positioning; sem ele, os r\xf3tulos ficam escondidos em vez de empilhados num canto */
@supports (position-anchor: --a) {
  .cg-label { display: block; bottom: anchor(top); left: anchor(center); translate: -50% 0; }
}
